import org.springframework.web.client.RestTemplate

class Service(private val restTemplate: RestTemplate) {
    private val items = listOf("a", "b", "c")

    fun fetchAll() {
        items.parallelStream().forEach { item -> restTemplate.getForObject("/api/$item", String::class.java) } // bad: blocks common pool
    }
}

import org.apache.commons.httpclient.HttpClient

class Service {
    private val items = listOf("a", "b", "c")
    fun fetchAll(client: HttpClient) {
        items.parallelStream().forEach { client.executeMethod(null) } // bad: blocking in common pool
    }
}

class Service {
    private val items = listOf(1, 2, 3, 4)
    fun compute() = items.parallelStream().mapToInt { it * 2 }.sum() // ok: CPU-only, no blocking
}

import org.springframework.web.client.RestTemplate
import java.util.concurrent.ForkJoinPool

class Service(private val restTemplate: RestTemplate) {
    private val pool = ForkJoinPool(10)
    private val items = listOf("a", "b")
    fun fetchAll() = pool.submit {
        items.parallelStream().forEach { restTemplate.getForObject("/api/$it", String::class.java) } // ok: custom pool
    }.get()
}
